$(document).on("WebPlayerSeIniciaSistema",function(){var control=Ciel.MPC.WebPlayer.Utilidad.ObtenerControl("PasoUno","TipoAtencion");if(!control||!control.DivContenedor){return;}
var rutaImagenes=Ciel.MPC.WebPlayer.RutaRecursos+"img/PasoUno/";var imagenes={"Cita presencial":"CitaPresencial.svg","Cita por videollamada":"CitaVideoLlamada.svg","default":"icon-help.svg"};control.callbackRepintarControl=function(objControl,divContenedor){var contenedor=objControl.DivContenedor[0];if(!contenedor){console.error('No se encontro el contenedor de tipos de atencion');return;}
var botons=contenedor.querySelectorAll('.boton');if(!botons||!botons.length){return;}
var arrayBoton=Array.from(botons);arrayBoton.forEach(function(element){var content=element;if(!content){console.error('No se encontro un contenedor de elementos en el boton');return;}
var spanBoton=content.querySelector('span');if(!spanBoton){console.error('No se logro obtener el span del boton tipo de atención');return;}
var textoCola=spanBoton.textContent;if(!textoCola){console.warn('No se encontro un texto para el boton tipo de atención');textoCola="";}
var texto=null;switch(textoCola.toLowerCase())
{case"virtual":case"cita por videollamada":textoCola="Cita por videollamada";texto="Videoatención";break;case"presencial":case"cita presencial":textoCola="Cita presencial";texto="Presencial";break;default:texto=textoCola;break;}
spanBoton.innerHTML=texto;var rutaImagen=imagenes[textoCola];if(!rutaImagen){rutaImagen=imagenes["default"];}
var imgCola=document.createElement("img");imgCola.setAttribute('src',rutaImagenes+rutaImagen);imgCola.classList.add('img-fluid');var divContentImg=document.createElement("div");divContentImg.append(imgCola);divContentImg.classList.add('contentImgTipoAtencion');content.prepend(divContentImg);});};control.subscriptores.push(function(control,contenedor){var divContenedor=contenedor.DivContenedor[0];if(!divContenedor){console.error('No se encontro el contenedor de tipos de persona.');return;}
var botones=divContenedor.querySelectorAll('.boton');if(!botones||!botones.length){console.error('No se encontraron tipos de atencion a mostrar.');return;}
botones.forEach(function(elemento){var llave=elemento.getAttribute('llave');if(!llave){return;}
var imgBoton=elemento.querySelector('.contentImgTipoAtencion');if(!imgBoton){return;}
if(llave==control.Llave){imgBoton.classList.add('filterSVG');return;}
imgBoton.classList.remove('filterSVG');});});});